contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val) public payable {
        require(true);

        bool revertedAfterInit;

        // initialize the contract
        c.Initialized(); if (__ESBMC_reverted()) return;

        // try to set MinSum after initialization; must revert
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedAfterInit = true;
        } else {
            revertedAfterInit = false;
        }

        assert(revertedAfterInit);
    }

    receive() external payable {}
}

